declare(strict_types=1);require __DIR__.'/../api/config.php';require __DIR__.'/includes/storage.php';$u=usuarioAtual();if(!$u){header('Location: ../login.php');exit;}$p=strtolower((string)($u['perfil']??$u['role']??$u['nivel']??''));$admin=!empty($u['is_admin'])||!empty($u['admin'])||$p==='admin'||strtolower((string)($u['login']??''))==='admin';if(!$admin){http_response_code(403);exit('Acesso restrito ao administrador.');}$f=orcamentosStorage().'/logs/processamentos.jsonl';$rows=[];if(is_file($f)){foreach(array_reverse(file($f,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[]) as $line){$x=json_decode($line,true);if(is_array($x))$rows[]=$x;if(count($rows)>=200)break;}}function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}?><?php $menuPage='monitoramento'; ?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Monitoramento</title><link rel="stylesheet" href="../assets/css/orcamentos/monitoramento.css"></head><body><?php require __DIR__ . '/includes/nav.php'; ?><div class="wrap"><div class="top"><div><h1>Monitoramento</h1><div class="muted">Últimos processamentos do gerador de orçamentos.</div></div></div><div class="table"><div class="row head"><div>Data</div><div>Locatário</div><div>Status</div><div>Tempo</div><div>Detalhes</div></div><?php foreach($rows as $r):?><div class="row"><div><?=h($r['created_at']??'')?></div><div><b><?=h($r['locatario']??'')?></b><div class="muted"><?=h($r['usuario']??'')?></div></div><div class="<?=($r['status']??'')==='OK'?'ok':'bad'?>"><?=h($r['status']??'')?></div><div><?=h($r['duration_ms']??'')?></div><div class="muted"><?=h($r['message']??$r['error']??'')?></div></div><?php endforeach;?><?php if(!$rows):?><div style="padding:20px" class="muted">Nenhum processamento registrado.</div><?php endif;?></div></div></body></html>
